#include <Aevrynd/SkinnedModelAsset.h>
#include <bit>
#include <cmath>
#include <iostream>

using namespace Aevrynd;
namespace {
SkinnedModel3D Model(){SkinnedModel3D model;model.bindMesh.vertices={{0,0,0,PackNormalSnorm8({0,1,0}),0xffffffffu,0,0},{1,0,0,PackNormalSnorm8({0,1,0}),0xffaabbccu,1,0},{0,1,0,PackNormalSnorm8({0,1,0}),0xff112233u,0,1}};model.bindMesh.indices={0,1,2};JointTransform3D child{};child.translation={1,0,0};child.scale={1,1,1};child.quaternion=NormalizeQuaternion3D({0,.1f,0,.99f});child.usesQuaternion=true;model.skeleton.joints={{-1,{}},{0,child}};model.influences={{{0,0,0,0},{65535,0,0,0}},{{1,0,0,0},{65535,0,0,0}},{{0,1,0,0},{32768,32767,0,0}}};model.inverseBindMatrices={Matrix4::Identity(),CreateTranslationMatrix({-1,0,0})};return model;}
void U32(std::vector<std::byte>& bytes,std::size_t offset,std::uint32_t value){for(unsigned shift=0;shift<32;shift+=8)bytes[offset++]=std::byte((value>>shift)&255);}
}

int main(int argumentCount,char** arguments){const SkinnedModel3D source=Model();std::vector<std::byte> encoded;std::string error;if(!EncodeSkinnedModelAsset(source,encoded,&error)||encoded.size()!=36+3*28+3*4+2*44+3*16+2*64){std::cerr<<"Encoding failed "<<error<<'\n';return 1;}const std::vector<std::byte> first=encoded;if(!EncodeSkinnedModelAsset(source,encoded)||encoded!=first){std::cerr<<"Encoding is not deterministic\n";return 2;}const SkinnedModelAssetResult loaded=LoadSkinnedModelAsset(encoded);if(!loaded||loaded.model.bindMesh.vertices.size()!=3||loaded.model.bindMesh.indices!=source.bindMesh.indices||loaded.model.skeleton.joints.size()!=2||!loaded.model.skeleton.joints[1].bindTransform.usesQuaternion||std::abs(loaded.model.skeleton.joints[1].bindTransform.quaternion.y-source.skeleton.joints[1].bindTransform.quaternion.y)>.0001f||loaded.model.influences[2].weights[0]!=32768||loaded.model.inverseBindMatrices[1][0][3]!=-1){std::cerr<<"Round trip failed\n";return 3;}
    std::vector<std::byte> damaged=encoded;damaged.pop_back();if(LoadSkinnedModelAsset(damaged)){std::cerr<<"Truncation was accepted\n";return 4;}damaged=encoded;U32(damaged,0,0);if(LoadSkinnedModelAsset(damaged)){std::cerr<<"Bad magic was accepted\n";return 5;}damaged=encoded;U32(damaged,24,UINT32_MAX);if(LoadSkinnedModelAsset(damaged)){std::cerr<<"Oversized count was accepted\n";return 6;}damaged=encoded;U32(damaged,36+3*28,9);if(LoadSkinnedModelAsset(damaged)){std::cerr<<"Bad mesh index was accepted\n";return 7;}damaged=encoded;const std::size_t firstJoint=36+3*28+3*4;U32(damaged,firstJoint,0);if(LoadSkinnedModelAsset(damaged)){std::cerr<<"Cyclic hierarchy was accepted\n";return 8;}damaged=encoded;U32(damaged,firstJoint+16,0);U32(damaged,firstJoint+20,0);U32(damaged,firstJoint+24,0);U32(damaged,firstJoint+28,0);if(LoadSkinnedModelAsset(damaged)){std::cerr<<"Zero quaternion was accepted\n";return 9;}damaged=encoded;const std::size_t firstInfluence=firstJoint+2*44;damaged[firstInfluence+8]=std::byte{1};damaged[firstInfluence+9]=std::byte{0};if(LoadSkinnedModelAsset(damaged)){std::cerr<<"Bad weight sum was accepted\n";return 10;}damaged=encoded;U32(damaged,36,0x7fc00000u);if(LoadSkinnedModelAsset(damaged)){std::cerr<<"NaN vertex was accepted\n";return 11;}
    std::vector<std::byte> sentinel{std::byte{7},std::byte{8}};SkinnedModel3D invalid=source;invalid.bindMesh.indices[0]=99;if(EncodeSkinnedModelAsset(invalid,sentinel,&error)||sentinel!=std::vector<std::byte>({std::byte{7},std::byte{8}})){std::cerr<<"Encoding failure was not atomic\n";return 11;}SkinnedModelLimits3D tiny;tiny.maximumVertices=2;if(LoadSkinnedModelAsset(encoded,tiny)){std::cerr<<"Limits were ignored\n";return 12;}if(argumentCount>1){const SkinnedModelAssetResult imported=LoadSkinnedModelAssetFile(arguments[1]);if(!imported||imported.model.bindMesh.vertices.size()!=114||imported.model.bindMesh.indices.size()!=672||imported.model.skeleton.joints.size()!=2){std::cerr<<"Converted glTF asset loading failed\n";return 13;}if(std::ranges::all_of(imported.model.bindMesh.vertices,[](const Vertex3D& vertex){return vertex.color==0xffffffffu;})){std::cerr<<"Converted glTF vertex colors were lost\n";return 14;}AnimationPose3D bindPose;SampleAnimationClipInto(imported.model.skeleton,{},0,bindPose);SkinningWorkspace3D workspace;Mesh3D skinned;if(!SkinModelInto(imported.model,bindPose,workspace,skinned)||skinned.vertices.size()!=imported.model.bindMesh.vertices.size()){std::cerr<<"Converted glTF bind pose skinning failed\n";return 15;}for(std::size_t index=0;index<skinned.vertices.size();++index){const Vertex3D& expected=imported.model.bindMesh.vertices[index],&actual=skinned.vertices[index];if(std::abs(expected.x-actual.x)>.001f||std::abs(expected.y-actual.y)>.001f||std::abs(expected.z-actual.z)>.001f){std::cerr<<"Converted glTF inverse bind mismatch\n";return 16;}}}std::cout<<"bytes="<<encoded.size()<<" vertices=3 joints=2 imported="<<(argumentCount>1?1:0)<<"\n";return 0;}
